try{$c=db();$r=queryParams($c,"SELECT id FROM projects WHERE name='ReleaseTracker Core'",[]);$pid=(int)pg_fetch_result($r,0,0);$ids=pg_fetch_all(queryParams($c,'SELECT id FROM issues WHERE project_id=$1 ORDER BY id LIMIT 3',[(string)$pid]));if(count($ids)<3)throw new RuntimeException('Need seed data');$a=(int)$ids[0]['id'];$b=(int)$ids[1]['id'];$d=(int)$ids[2]['id'];pg_query($c,'BEGIN');DependencyService::add($c,$pid,$a,$b);DependencyService::add($c,$pid,$b,$d);$caught=false;try{DependencyService::add($c,$pid,$d,$a);}catch(Throwable $e){$caught=str_contains($e->getMessage(),'vòng');}if(!$caught)throw new RuntimeException('Cycle was not rejected');pg_query($c,'ROLLBACK');echo "PASS cycle dependency rejected\n";echo "INTEGRATION=1 FAILED=0\n";}catch(Throwable $e){if(isset($c))@pg_query($c,'ROLLBACK');fwrite(STDERR,'FAIL '.$e->getMessage()."\n");exit(1);}
